<?php
require_once dirname(__DIR__).'/config.php';
$conn=db();
$eventId=(int)($_GET['event_id']??0);
$status=trim($_GET['status']??'');
$search=trim($_GET['search']??'');
$where=[];$params=[];$types='';
if($eventId){$where[]='a.event_id=?';$params[]=$eventId;$types.='i';}
if($status){$where[]='a.attendance_status=?';$params[]=$status;$types.='s';}
if($search){$where[]='(s.student_no LIKE CONCAT("%",? ,"%") OR s.first_name LIKE CONCAT("%",? ,"%") OR s.last_name LIKE CONCAT("%",? ,"%"))';$params[]=$search;$params[]=$search;$params[]=$search;$types.='sss';}
$sql="SELECT a.*,e.event_name,e.event_date,s.student_no,s.first_name,s.last_name,s.course,s.year_level,s.section FROM event_attendance a JOIN events e ON e.id=a.event_id JOIN students s ON s.id=a.student_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY e.event_date DESC,a.attendance_id DESC LIMIT 1000";
$stmt=$conn->prepare($sql);
if($params){$bind=[$types];foreach($params as $i=>$v)$bind[]=&$params[$i];call_user_func_array([$stmt,'bind_param'],$bind);}
$stmt->execute();$rows=$stmt->get_result();
if(isset($_GET['export'])&&$_GET['export']==='csv'){
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="student-attendance.csv"');
    $output=fopen('php://output','w');fputcsv($output,['Student','Student ID','Course / Section','Event','Date','In','Out','Status']);
    while($row=$rows->fetch_assoc()){fputcsv($output,[$row['last_name'].', '.$row['first_name'],$row['student_no'],trim(($row['course']??'').' '.($row['year_level']??'').' '.($row['section']??'')),$row['event_name'],$row['event_date'],$row['scan_in']?:'--',$row['scan_out']?:'--',$row['attendance_status']]);}fclose($output);exit;
}
$events=$conn->query('SELECT id,event_name,event_date FROM events ORDER BY event_date DESC');
$pageTitle='Attendance Reports';ob_start();
?><div class="space-y-6"><div class="rounded-2xl bg-white p-5 shadow"><div class="mb-4 flex flex-wrap items-center justify-between gap-3 print:hidden"><div class="text-lg font-semibold">Student attendance</div><div class="flex flex-wrap gap-2"><a href="?export=csv&amp;event_id=<?php echo $eventId; ?>&amp;status=<?php echo urlencode($status); ?>&amp;search=<?php echo urlencode($search); ?>" class="rounded border border-slate-300 bg-white px-3 py-2 text-sm text-slate-700 hover:bg-slate-50">Download CSV</a><button type="button" onclick="window.print()" class="rounded border border-slate-300 bg-white px-3 py-2 text-sm text-slate-700 hover:bg-slate-50">Save PDF</button></div></div><div class="hidden text-lg font-semibold print:block">Student attendance</div><form class="grid gap-3 md:grid-cols-4 print:hidden"><select name="event_id" class="rounded border px-3 py-2"><option value="0">All events</option><?php while($event=$events->fetch_assoc()):?><option value="<?php echo (int)$event['id']; ?>" <?php echo $eventId===(int)$event['id']?'selected':''; ?>><?php echo h($event['event_name'].' - '.$event['event_date']); ?></option><?php endwhile; ?></select><select name="status" class="rounded border px-3 py-2"><option value="">All statuses</option><?php foreach(['PRESENT','ABSENT','LATE','EXCUSED','INCOMPLETE'] as $option):?><option value="<?php echo $option; ?>" <?php echo $status===$option?'selected':''; ?>><?php echo $option; ?></option><?php endforeach; ?></select><input name="search" value="<?php echo h($search); ?>" placeholder="Student ID or name" class="rounded border px-3 py-2"><button class="rounded bg-slate-900 px-3 py-2 text-white">Apply filters</button></form><div class="mt-4 overflow-x-auto"><table class="min-w-full text-sm"><thead><tr class="border-b text-left"><th class="px-2 py-2">Student</th><th class="px-2 py-2">Event / Date</th><th class="px-2 py-2">In</th><th class="px-2 py-2">Out</th><th class="px-2 py-2">Status</th></tr></thead><tbody><?php if($rows->num_rows):while($row=$rows->fetch_assoc()):?><tr class="border-b align-top"><td class="px-2 py-3 font-medium"><?php echo h($row['last_name'].', '.$row['first_name']); ?><div class="text-xs text-slate-500"><?php echo h($row['student_no'].' · '.trim(($row['course']??'').' '.($row['year_level']??'').' '.($row['section']??''))); ?></div></td><td class="px-2 py-3"><?php echo h($row['event_name']); ?><div class="text-xs text-slate-500"><?php echo h($row['event_date']); ?></div></td><td class="px-2 py-3"><?php echo h($row['scan_in']?:'--'); ?></td><td class="px-2 py-3"><?php echo h($row['scan_out']?:'--'); ?></td><td class="px-2 py-3"><?php echo h($row['attendance_status']); ?></td></tr><?php endwhile;else:?><tr><td colspan="5" class="px-2 py-6 text-center text-slate-500">No attendance records found.</td></tr><?php endif; ?></tbody></table></div></div></div><style>@page{margin:0}@media print{aside,.admin-content>header,.admin-content>footer{display:none!important}.admin-content{margin-left:0!important}.admin-content main{padding:12mm!important}.admin-content main>div{box-shadow:none!important}.admin-content table{font-size:11px}}</style><?php $content=ob_get_clean();include __DIR__.'/_layout.php';
